insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('avatars','avatars',true,5242880,array['image/jpeg','image/png','image/webp']),('evidence','evidence',false,10485760,array['image/jpeg','image/png','application/pdf']) on conflict(id) do update set public=excluded.public;
create table private.evidence_objects (id uuid primary key default gen_random_uuid(), bucket_id text not null default 'evidence', object_path text not null unique, owner_player_id uuid not null references public.players, purpose text not null, content_type text not null, size_bytes bigint not null, finalized_at timestamptz, retention_until timestamptz, legal_hold_at timestamptz, deleted_at timestamptz, created_at timestamptz not null default now());
create policy avatar_public_read on storage.objects for select using (bucket_id='avatars');
create policy avatar_owner_write on storage.objects for insert to authenticated with check (bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text);
